var body = $input.first().json.body || {};
var project = body.project || 'candlekeep/candlekeep-backend';
var container = body.container || 'candlekeep-backend';
var targetFile = body.targetFile || '';
var method = body.method || '';
var insertAfter = body.insertAfter || null;
// optional: public|private|protected — where the new method lands (see ast_patch_ruby.rb --visibility)
var visibility = ['public', 'private', 'protected'].indexOf(body.visibility) !== -1 ? body.visibility : null;
// optional: generator model (allow-list). 3b equals 7b on simple pieces at 5x speed, fails on structure-building helpers.
var MODELS = ['qwen2.5-coder:7b', 'qwen2.5-coder:3b'];
var model = MODELS.indexOf(body.model) !== -1 ? body.model : 'qwen2.5-coder:7b';
var systemPrompt = body.systemPrompt || 'You are a senior Ruby on Rails engineer working in this exact codebase. Follow the existing code style precisely. Output ONLY the method source code, starting with def and ending with end. Never include a visibility keyword (private, public, protected) or any surrounding class/module — just the raw def...end block. No markdown fences, no explanation.';
var taskDescription = body.taskDescription || '';
var rubyVersion = body.rubyVersion || '3.2';
return [{ json: {
  project: project,
  container: container,
  targetFile: targetFile,
  method: method,
  insertAfter: insertAfter,
  visibility: visibility,
  model: model,
  systemPrompt: systemPrompt,
  taskDescription: taskDescription,
  rubyVersion: rubyVersion
} }];

var msg = $input.first().json.message;
var raw = (msg && msg.content) ? msg.content : '';
var cleaned = raw.replace(/^```[a-zA-Z]*\n?/, '').replace(/```\s*$/, '').trim();
cleaned = cleaned.replace(/^(private|public|protected)\s*\n+/, '').trim();
var valid = cleaned.indexOf('def ') === 0;
return [{ json: {
  methodBody: cleaned,
  valid: valid,
  reason: valid ? null : "qwen response did not start with 'def ' after stripping markdown fences/visibility keyword"
} }];

var resp = $input.first().json;
var targetFile = $('Build Patch Command').first().json.targetFile;
var method = $('Build Patch Command').first().json.method;
var parsed = null;
var parseError = null;
try { parsed = JSON.parse(resp.stdout); } catch (e) { parseError = e.message; }
var ok = resp.exitCode === 0 && parsed && parsed.ok === true;
return [{ json: {
  filesWritten: ok ? 1 : 0,
  generatedFiles: ok ? [{ path: targetFile, content: parsed.content, language: 'ruby' }] : [],
  action: (parsed && parsed.action) ? parsed.action : null,
  method: method,
  visibility: (parsed && parsed.visibility) ? parsed.visibility : null,
  model: $('Normalize Input').first().json.model,
  error: ok ? null : ((parsed && parsed.error) ? parsed.error : (parseError || resp.stderr || ('docker-bridge exec failed, exitCode ' + resp.exitCode))),
  summary: ok ? ('1 fichier patche (' + parsed.action + ' ' + method + ', ' + parsed.visibility + ')') : '0 fichier patche'
} }];

return [{ json: {
  filesWritten: 0,
  generatedFiles: [],
  error: $json.reason,
  summary: '0 fichier patche - reponse qwen invalide'
} }];
